import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireForms Release Notes — 2025","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireForms/aireforms-2025.md","filePath":"aireblock-releases/AireForms/aireforms-2025.md","lastUpdated":1786967125000}`),a={name:`aireblock-releases/AireForms/aireforms-2025.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireforms-release-notes-—-2025" tabindex="-1"><span class="fsc-product"><img src="/aireforms-icon.png"> AireForms Release Notes — 2025</span> <a class="header-anchor" href="#aireforms-release-notes-—-2025" aria-label="Permalink to “AireForms Release Notes — 2025”">​</a></h1><p>This page contains the AireForms releases published during 2025.</p><h2 id="version-10-11-2-—-form-metrics" tabindex="-1">Version 10.11.2 — Form Metrics <a class="header-anchor" href="#version-10-11-2-—-form-metrics" aria-label="Permalink to “Version 10.11.2 — Form Metrics”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 24, 2025</p></blockquote><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added a Form Metrics page to the admin screen</li><li>The new page provides a view of form actions over time</li><li>Access to the Form Metrics page requires a new user permission</li></ul><h3 id="i️-notes" tabindex="-1">ℹ️ Notes <a class="header-anchor" href="#i️-notes" aria-label="Permalink to “ℹ️ Notes”">​</a></h3><ul><li>Metrics data collection starts from the point this version is released as the Forms runtime</li></ul><h2 id="version-10-10-0-—-history-api-authorisation-accessibility" tabindex="-1">Version 10.10.0 — History API Authorisation &amp; Accessibility <a class="header-anchor" href="#version-10-10-0-—-history-api-authorisation-accessibility" aria-label="Permalink to “Version 10.10.0 — History API Authorisation &amp; Accessibility”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 24, 2025</p></blockquote><h3 id="⚠️-possible-breaking-changes" tabindex="-1">⚠️ Possible Breaking Changes <a class="header-anchor" href="#⚠️-possible-breaking-changes" aria-label="Permalink to “⚠️ Possible Breaking Changes”">​</a></h3><ul><li>The History API now requires a user to pass the <code>ListPatientForms</code> authorisation check via the plugin</li></ul><h3 id="♿-accessibility" tabindex="-1">♿ Accessibility <a class="header-anchor" href="#♿-accessibility" aria-label="Permalink to “♿ Accessibility”">​</a></h3><ul><li>Various accessibility improvements</li></ul><h2 id="version-10-9-1-—-aireidentity-tenanted-login" tabindex="-1">Version 10.9.1 — AireIdentity Tenanted Login <a class="header-anchor" href="#version-10-9-1-—-aireidentity-tenanted-login" aria-label="Permalink to “Version 10.9.1 — AireIdentity Tenanted Login”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 6, 2025</p></blockquote><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for AireIdentity tenanted login to Single Pass Authentication</li></ul><h2 id="version-10-9-0-—-form-instance-discarded-event" tabindex="-1">Version 10.9.0 — Form Instance Discarded Event <a class="header-anchor" href="#version-10-9-0-—-form-instance-discarded-event" aria-label="Permalink to “Version 10.9.0 — Form Instance Discarded Event”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 6, 2025</p></blockquote><h3 id="✨-new-features-2" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-2" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added a new <code>FormInstanceDiscarded</code> event for other AireSuite products to subscribe to</li></ul><h3 id="♿-accessibility-1" tabindex="-1">♿ Accessibility <a class="header-anchor" href="#♿-accessibility-1" aria-label="Permalink to “♿ Accessibility”">​</a></h3><ul><li>Added missing focus highlights to radio buttons and checkboxes</li></ul><h2 id="version-10-8-2-—-patient-forms-api-performance" tabindex="-1">Version 10.8.2 — Patient Forms API Performance <a class="header-anchor" href="#version-10-8-2-—-patient-forms-api-performance" aria-label="Permalink to “Version 10.8.2 — Patient Forms API Performance”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 21, 2025</p></blockquote><h3 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved the performance of some <code>/api/patientforms/*</code> API calls</li></ul><h2 id="version-10-8-1-—-font-loading-fix" tabindex="-1">Version 10.8.1 — Font Loading Fix <a class="header-anchor" href="#version-10-8-1-—-font-loading-fix" aria-label="Permalink to “Version 10.8.1 — Font Loading Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 21, 2025</p></blockquote><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue with font loading</li></ul><h2 id="version-10-8-0-—-single-pass-success-message-fix" tabindex="-1">Version 10.8.0 — Single Pass Success Message Fix <a class="header-anchor" href="#version-10-8-0-—-single-pass-success-message-fix" aria-label="Permalink to “Version 10.8.0 — Single Pass Success Message Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 21, 2025</p></blockquote><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where a Single Pass form-level custom success message was not displayed when the organisation configuration included a custom redirect</li></ul><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Various style-scoping changes were made in preparation for new functionality when AireForms is used within AireFrame</li></ul><h2 id="version-10-7-0-—-rich-text-extract-v2-aireglu-subject-provider" tabindex="-1">Version 10.7.0 — Rich Text, Extract V2 &amp; AireGlu Subject Provider <a class="header-anchor" href="#version-10-7-0-—-rich-text-extract-v2-aireglu-subject-provider" aria-label="Permalink to “Version 10.7.0 — Rich Text, Extract V2 &amp; AireGlu Subject Provider”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 11, 2025</p></blockquote><h3 id="⚡-improvements-2" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-2" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved cross-building-block errors to include the source building block and control containing the XPath</li><li>Added first-class support for the AireGlu Subject Provider in the Persisted Deliverer</li><li>Updated the plugin to version 4.5.0, including extension support for registering custom OpenTelemetry metrics and traces</li></ul><h3 id="🐞-bug-fixes-2" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-2" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Worked around an issue with empty lines in Rich Text caused by changes in the underlying Quill.js library</li><li>Extract V2 now ignores non-relevant building blocks when using a building block extract</li><li>Non-relevant building blocks remain exposed on form extracts</li></ul><h2 id="version-10-6-2-—-rich-text-form-layout-fixes" tabindex="-1">Version 10.6.2 — Rich Text &amp; Form Layout Fixes <a class="header-anchor" href="#version-10-6-2-—-rich-text-form-layout-fixes" aria-label="Permalink to “Version 10.6.2 — Rich Text &amp; Form Layout Fixes”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 7, 2025</p></blockquote><h3 id="🐞-bug-fixes-3" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-3" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where Rich Text was incorrectly formatted in view mode</li><li>Fixed an issue where using the maximum number of columns at certain widths could cause the form layout to overflow the page</li></ul><h2 id="version-10-6-1-—-numbered-list-improvements" tabindex="-1">Version 10.6.1 — Numbered List Improvements <a class="header-anchor" href="#version-10-6-1-—-numbered-list-improvements" aria-label="Permalink to “Version 10.6.1 — Numbered List Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 2, 2025</p></blockquote><h3 id="⚡-improvements-3" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-3" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved the spacing of numbered lists in explanatory text within generated PDFs</li></ul><h3 id="🐞-bug-fixes-4" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-4" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where numbered lists in Rich Text were incorrectly displayed as bullet lists</li></ul><h2 id="version-10-6-0-—-designer-xpath-form-context-improvements" tabindex="-1">Version 10.6.0 — Designer XPath &amp; Form Context Improvements <a class="header-anchor" href="#version-10-6-0-—-designer-xpath-form-context-improvements" aria-label="Permalink to “Version 10.6.0 — Designer XPath &amp; Form Context Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 14, 2025</p></blockquote><h3 id="⚡-improvements-4" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-4" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Added the instance GUID to the composite form context</li></ul><h3 id="🐞-bug-fixes-5" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-5" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed issues when saving a building block containing a union XPath in the Designer</li></ul><h2 id="version-10-5-0-—-score-control-fix" tabindex="-1">Version 10.5.0 — Score Control Fix <a class="header-anchor" href="#version-10-5-0-—-score-control-fix" aria-label="Permalink to “Version 10.5.0 — Score Control Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 18, 2025</p></blockquote><h3 id="🐞-bug-fixes-6" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-6" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where the Score control did not correctly rehydrate the reversed flag in the Designer</li></ul><h2 id="version-10-4-0-—-aireforms-rebrand" tabindex="-1">Version 10.4.0 — AireForms Rebrand <a class="header-anchor" href="#version-10-4-0-—-aireforms-rebrand" aria-label="Permalink to “Version 10.4.0 — AireForms Rebrand”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 4, 2025</p></blockquote><h3 id="✨-product-update" tabindex="-1">✨ Product Update <a class="header-anchor" href="#✨-product-update" aria-label="Permalink to “✨ Product Update”">​</a></h3><ul><li>Rebranded Forms4Health to AireForms</li></ul><h2 id="version-10-3-0-—-extract-v2-correlation-id" tabindex="-1">Version 10.3.0 — Extract V2 Correlation ID <a class="header-anchor" href="#version-10-3-0-—-extract-v2-correlation-id" aria-label="Permalink to “Version 10.3.0 — Extract V2 Correlation ID”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 3, 2025</p></blockquote><h3 id="⚡-improvements-5" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-5" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Extract V2 responses now return the <code>CorrelationId</code></li></ul><h2 id="version-10-2-0-—-prototype-forms-in-sandbox-environments" tabindex="-1">Version 10.2.0 — Prototype Forms in Sandbox Environments <a class="header-anchor" href="#version-10-2-0-—-prototype-forms-in-sandbox-environments" aria-label="Permalink to “Version 10.2.0 — Prototype Forms in Sandbox Environments”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 20, 2025</p></blockquote><h3 id="⚡-improvements-6" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-6" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Forms marked as Prototype can now be created in sandbox environments</li></ul><h3 id="🔧-dependencies" tabindex="-1">🔧 Dependencies <a class="header-anchor" href="#🔧-dependencies" aria-label="Permalink to “🔧 Dependencies”">​</a></h3><ul><li>Updated Forms.Api to 4.4.0, including a new <code>SystemUserIdentifier</code> type used in authorisation</li><li>Updated Forms.Persistence to 3.4.0, adding <code>External</code> to <code>UserIdentifierType</code></li></ul><h2 id="version-10-1-0-—-external-form-authors" tabindex="-1">Version 10.1.0 — External Form Authors <a class="header-anchor" href="#version-10-1-0-—-external-form-authors" aria-label="Permalink to “Version 10.1.0 — External Form Authors”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 2, 2025</p></blockquote><h3 id="✨-new-features-3" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-3" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added the ability to specify an XPath on Persisted Deliverer configuration to define an external author when a form is persisted</li></ul><h3 id="🔧-dependencies-1" tabindex="-1">🔧 Dependencies <a class="header-anchor" href="#🔧-dependencies-1" aria-label="Permalink to “🔧 Dependencies”">​</a></h3><ul><li>Updated Forms.Api to 4.3.0, including the new <code>SystemUserIdentifier</code> type used in authorisation</li><li>Updated Forms.Persistence to 3.3.0, adding <code>External</code> to <code>UserIdentifierType</code></li></ul><h2 id="version-10-0-0-—-opentelemetry-plugin-loading" tabindex="-1">Version 10.0.0 — OpenTelemetry &amp; Plugin Loading <a class="header-anchor" href="#version-10-0-0-—-opentelemetry-plugin-loading" aria-label="Permalink to “Version 10.0.0 — OpenTelemetry &amp; Plugin Loading”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 30, 2025</p></blockquote><h3 id="⚡-improvements-7" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-7" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Added OpenTelemetry support</li></ul><h3 id="⚠️-breaking-changes" tabindex="-1">⚠️ Breaking Changes <a class="header-anchor" href="#⚠️-breaking-changes" aria-label="Permalink to “⚠️ Breaking Changes”">​</a></h3><ul><li>Changed how plugins are loaded</li><li>Plugin project files require changes to support the new loading approach</li></ul><h3 id="🐞-bug-fixes-7" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-7" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed styling issues with repeats in the Designer</li><li>Relaxed XPath validation when using parent references in the Designer</li></ul><h2 id="version-9-6-4-—-previously-submitted-context-fix" tabindex="-1">Version 9.6.4 — Previously Submitted Context Fix <a class="header-anchor" href="#version-9-6-4-—-previously-submitted-context-fix" aria-label="Permalink to “Version 9.6.4 — Previously Submitted Context Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 13, 2025</p></blockquote><h3 id="🐞-bug-fixes-8" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-8" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where the <code>internal-previously-submitted</code> form context value was incorrectly calculated on the first amendment of a completed form</li></ul><h2 id="version-9-6-3-—-submitted-form-retrieval-performance" tabindex="-1">Version 9.6.3 — Submitted Form Retrieval Performance <a class="header-anchor" href="#version-9-6-3-—-submitted-form-retrieval-performance" aria-label="Permalink to “Version 9.6.3 — Submitted Form Retrieval Performance”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 10, 2025</p></blockquote><h3 id="⚡-improvements-8" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-8" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved database calls used when retrieving submitted form information</li></ul><h2 id="version-9-6-2-—-persisted-deliverer-wizard-form-fix" tabindex="-1">Version 9.6.2 — Persisted Deliverer Wizard Form Fix <a class="header-anchor" href="#version-9-6-2-—-persisted-deliverer-wizard-form-fix" aria-label="Permalink to “Version 9.6.2 — Persisted Deliverer Wizard Form Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> January 7, 2025</p></blockquote><h3 id="🐞-bug-fixes-9" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-9" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where Wizard forms configured to use the Persisted Deliverer could not be submitted</li></ul>`,104)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};